/** Three throwaway layouts on /prototype/?variant=A|B|C. Await visual approval before a production build. */
import './style.css';
import './theme-fonts.css';
import './themes.css';
import './cyber-theme.css';
import './system-theme.css';
import './house-menu.css';
import { state, residents, exchanges, resident, update, subscribe, select, pauseTown, pauseResident, decide, accept, replay, setTheme, setVariant, toast, type Variant, towns, currentTown, activeResidents, switchTown, foundTown, expandCity, consolidateCity, recallResident, relayout, clockLabel, clockHours, setClockMode, previewDemand, chief, residentName } from './state';
import { TownScene } from './scene';
import { icon } from './icons';

if(location.pathname==='/')history.replaceState({},'','/prototype/'+location.search);
const app=document.querySelector<HTMLDivElement>('#app')!;
app.innerHTML=`<div class="app-shell">
 <header class="app-header" id="header"></header>
 <nav class="side-rail" id="rail" aria-label="City navigation"></nav>
 <main class="workspace" id="workspace">
  <div class="desktop-preview" id="desktop"></div>
  <div class="canvas-host" id="scene"></div>
  <section class="town-heading" id="heading" aria-label="City summary"></section>
  <section class="goal-summary" id="goal-summary" aria-label="Current goal"></section>
  <section class="command-home" id="command-home"></section>
  <div class="map-overline"><span class="live-point"></span><span id="scene-state">Demo district</span></div>
  <div class="compact-chrome" id="compact-chrome"></div><div class="city-actions" id="city-actions"></div><div class="world-clock" id="world-clock"></div>
  <div class="map-controls" id="map-controls" aria-label="City view controls"></div>
  <div class="map-legend" id="map-legend"></div>
  <div id="panel-slot"></div>
  <section class="residents-strip" id="roster" aria-label="Residents"></section>
  <footer class="workspace-footer" id="footer"></footer>
 </main>
 <div class="prototype-switcher" id="switcher" aria-label="Prototype layouts"></div>
 <div class="toast" id="toast" role="status" aria-live="polite"></div>
 <div id="modal-slot"></div>
</div>`;
// Canvas signs must be drawn after the same theme faces used by the DOM are ready.
await Promise.all(['400 16px "Friend or Foe Tall BB"','400 16px Abel','500 16px Rajdhani','700 16px Rajdhani'].map(font=>document.fonts.load(font).catch(()=>[])));
const scene=new TownScene(document.querySelector('#scene')!);
Object.assign(window,{__agentCityPrototype:{state,residents,exchanges,towns,rendererStats:()=>scene.stats()}});
Object.assign(window,{__townPrototype:(window as unknown as Record<string,unknown>).__agentCityPrototype});
const el=(id:string)=>document.getElementById(id)!;
const esc=(v:string)=>v.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const active=(r:typeof residents[number])=>['Reading','Researching'].includes(r.activity);
const statusClass=(s:string)=>s==='Needs approval'?'attention':s==='Paused'||s==='Pausing'?'muted':s==='Reading'||s==='Researching'?'working':'';
const home=(r:typeof residents[number])=>state.theme==='cyber'?r.home:r.shadowHome;
const townName=()=>esc(currentTown().name);
const tag=(text:string,cls='')=>`<span class="tag ${cls}">${text}</span>`;
function avatar(r:typeof residents[number],large=false){
 const shadow=state.theme==='shadow';
 const base='<path class="portrait-body" d="M2 40c1-10 6-15 16-15s15 5 16 15Z"/><path class="portrait-jacket" d="M7 40 10 28l8-3 8 3 3 12Z"/>';
 const human='<path class="portrait-head" d="M10 13c0-10 16-10 16 0v6c0 6-5 10-8 10s-8-4-8-10Z"/><path class="portrait-hair" d="M9 17V9c1-9 17-9 18 1v8l-4-7c-3 3-7 2-10 1l-2 7Z"/><path fill="#e6e9df" d="M11 17h5v3h-5zm9 0h5v3h-5Z"/><path fill="#20323c" d="M13 17h2v3h-2zm8 0h2v3h-2Z"/><path d="M18 19v4m-3 2h6" fill="none" stroke="#8c625a" stroke-width=".8"/><path class="portrait-collar" d="m8 29 5-3 5 7 5-7 5 3-6 11h-8Z"/>';
 const shadowHeads:Record<string,string>={
  mayor:'<path fill="#a6445d" d="M17 10c-4-7-1-11 3-10l3 2c-4 1-4 5-3 8Z"/><path class="portrait-head" d="m10 13 8-8 8 8-2 13-6 4-6-4Z"/><path class="portrait-hair" d="m9 17 9-11 9 11-6-3-3 5-3-5Z"/><path class="portrait-visor" d="m11 18 5 1-1 2-4-1m14-2-5 1 1 2 4-1Z"/><path fill="#6386b2" d="m17 17 2 0 1 10-2 3-2-3Z"/>',
  scout:'<path class="portrait-body" d="m3 30-3-12 11 8m22 4 3-12-11 8Z"/><path class="portrait-head" d="m9 12-3-8 7 5h10l7-5-3 8-1 8-8 8-8-8Z"/><path fill="#526d94" d="m11 18 7-3 7 3-2 7-5 4-5-4Z"/><path class="portrait-visor" d="m11 14 5 1-1 3-4-2m14-2-5 1 1 3 4-2Z"/>',
  reader:'<path fill="#7182a7" d="M10 13 6 4l7 5h10l7-5-4 9Z"/><path class="portrait-head" d="M8 13q10-10 20 0l-2 13-8 5-8-5Z"/><path fill="#778ab0" d="m10 21 8-2 8 2-2 8H12Z"/><path fill="#e0d0b2" d="m12 27-2-8 5 7m9 1 2-8-5 7Z"/><path class="portrait-visor" d="M10 15h6v3h-6zm10 0h6v3h-6Z"/>',
  analyst:'<path fill="#7f9bc1" d="m8 16-7-10 10 4h14l10-4-7 10Z"/><path class="portrait-head" d="m8 14 10-7 10 7v12l-10 5-10-5Z"/><path fill="#3b547a" d="M9 18h18v8l-9 5-9-5Z"/><path class="portrait-visor" d="M11 17h5v3h-5zm9 0h5v3h-5Z"/>',
  editor:'<circle class="portrait-hair" cx="9" cy="11" r="6"/><circle class="portrait-hair" cx="27" cy="11" r="6"/><path class="portrait-head" d="M6 17C6 4 30 4 30 17v6c-2 9-22 9-24 0Z"/><ellipse fill="#597da6" cx="18" cy="24" rx="9" ry="6"/><ellipse fill="#17283c" cx="18" cy="21" rx="4" ry="3"/><path class="portrait-visor" d="M9 15h6v3H9zm12 0h6v3h-6Z"/>',
  critic:'<path class="portrait-head" d="M9 18C8 2 28 2 27 18l-4 10h-10Z"/><path d="m13 10-4-9m14 9 4-9" stroke="#b19eea" stroke-width="1.5"/><path class="portrait-visor" d="m10 15 6 2-2 3-4-2m16-3-6 2 2 3 4-2Z"/><path fill="#8496bc" d="m11 22 5 2-2 7-5-5m16-4-5 2 2 7 5-5Z"/>'
 };
 const generic='<path class="portrait-head" d="m10 13 8-8 8 8-2 13-6 4-6-4Z"/><path class="portrait-hair" d="m9 14 9-10 9 10-9 4Z"/><path class="portrait-visor" d="M11 18h5v3h-5zm9 0h5v3h-5Z"/>';
 return `<span class="avatar avatar-${r.id} ${large?'large':''}" aria-hidden="true"><svg viewBox="0 0 36 40">${base}${shadow?(shadowHeads[r.id]||generic):human}${r.role==='Reader'?'<path fill="#b4c8db" d="M22 29h10v10H22z"/>':''}</svg><span class="avatar-status ${statusClass(r.activity)}"></span></span>`;
}

function header(){return `<a href="/prototype/" class="brand" aria-label="Agent City home">${icon('town')}<span>agent<span class="brand-light">city</span><span class="brand-period">.</span></span></a>
 <div class="header-divider"></div><button class="workspace-name" data-action="towns" aria-label="Manage towns">${townName()} <span class="town-count">${towns.length} ${towns.length===1?'town':'towns'}</span>${icon('chevron')}</button>
 <div class="header-center"><span class="local-dot"></span>LOCAL FIRST<span class="header-slash">/</span><span>YOUR AGENTS, AT HOME</span></div>
 <div class="theme-switch" role="group" aria-label="Visual theme"><button data-theme="cyber" class="${state.theme==='cyber'?'is-active':''}" aria-pressed="${state.theme==='cyber'}">${icon('bolt')}<span>Cyberpunk</span></button><button data-theme="shadow" class="${state.theme==='shadow'?'is-active':''}" aria-pressed="${state.theme==='shadow'}">${icon('spark')}<span>Solo Leveling</span></button></div>
 <button class="demo-badge" data-action="about"><span></span>DEMO</button><button class="icon-button settings-header" data-action="settings" aria-label="Settings">${icon('settings')}</button>`;}
function rail(){return `<div class="rail-top">${[['town','City','town'],['users','Residents','residents'],['tasks','Tasks','goal'],['shield','Approvals','approvals'],['activity','Activity','activity'],['archive','Accepted outcomes','outcomes']].map(([ic,label,action])=>`<button class="rail-button ${(action==='town'&&!state.panel)||(action==='residents'&&state.panel==='resident')||action===state.panel?'active':''}" aria-label="${label}" title="${label}" data-action="${action}">${icon(ic)}${action==='approvals'&&state.approval==='pending'?'<span class="nav-dot"></span>':''}</button>`).join('')}</div><div class="rail-bottom"><button class="rail-button" data-action="about" aria-label="About the prototype">${icon('help')}</button><button class="owner-avatar" data-action="chief" aria-label="Chief headquarters" title="Chief headquarters">C</button></div>`;}
function heading(){return `<div class="eyebrow"><span class="tiny-square"></span>${state.theme==='cyber'?'DISTRICT 01':'SHADOW DOMAIN 01'}<span class="muted"> / </span> ${state.stage===0?'ESTABLISHMENT':state.stage===1?'EXPANSION':'CONSOLIDATION'}</div><div class="heading-line"><h1>${townName()}<span class="title-dot">.</span></h1><span class="town-state">${state.paused?'City paused':state.phase==='accepted'?'Settled & quiet':'A little work in progress'}</span></div><p>${state.theme==='cyber'?'Good work has a place to call home.':'A quiet domain. A capable council.'}</p><div class="town-metrics"><span>${icon('users')} ${activeResidents().length} residents</span><span class="metric-divider"></span><span><i class="status-dot active"></i> ${activeResidents().filter(active).length} working</span><span class="metric-divider"></span><button data-action="outcomes">${icon('check')} ${state.accepted} accepted outcomes</button></div>`;}
function goalSummary(){if(state.phase==='idle')return `<div class="eyebrow">A NEW BEGINNING</div><h3>A town with room for your next idea.</h3><p class="idle-copy">Your new team is at home. No work runs until you assign it.</p><button class="button primary full-width" data-action="assign">${icon('plus')}Give the first goal</button>`;return `<div class="section-line"><span class="eyebrow">${state.phase==='accepted'?'LATEST OUTCOME':'CURRENT GOAL'}</span><span class="tiny-code">G-003</span></div><h3>${esc(state.goal)}</h3><div class="goal-owner">${avatar(resident('mayor'))}<span>${residentName(resident('mayor'))} is ${state.phase==='accepted'?'at home':state.phase==='review'?'ready for your review':'coordinating'}</span></div><div class="goal-progress"><span style="width:${state.phase==='working'?'45':'100'}%"></span></div><div class="goal-bottom"><span>${state.phase==='working'?'2 of 4 deliverables':state.phase==='review'?'Ready for your review':'Accepted by you'}</span><button data-action="goal">${state.phase==='review'?'Review result':'View plan'} ${icon('arrow')}</button></div>${state.approval==='pending'?`<button class="attention-link" data-action="approvals"><span class="attention-dot"></span>1 decision needs you ${icon('chevron')}</button>`:''}`;}
function controls(){return `${state.peek?'<button class="replay-button cutaway-close" data-action="close-cutaway">Close cutaway</button>':''}<div class="view-button-group"><button data-action="settings" aria-label="Day and night settings" title="Clock-driven world lighting">${icon(clockHours()>6&&clockHours()<19?'sun':'moon')}<span>${state.clockMode==='local'?'Local time':state.clockMode==='accelerated'?'90s cycle':'Fixed'}</span></button><span class="control-divider"></span><button data-action="quiet" aria-label="${state.quiet?'Enable':'Disable'} animation" class="${state.quiet?'control-active':''}" title="Quiet mode">${icon('volume')}</button><button data-action="roads" aria-label="Toggle route markings" aria-pressed="${state.roads}" title="Route markings" class="${state.roads?'control-active':''}">${icon('route')}</button></div><div class="view-button-group zoom-controls"><button data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button><button data-action="reset-camera" aria-label="Reset camera" class="zoom-value">${Math.round(state.zoom*100)}%</button><button data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button></div><button class="orbit-button" data-action="orbit" aria-label="Rotate city" title="Rotate 45°. Right-drag or Option/Alt-drag to orbit and tilt">${icon('reset')}</button><button class="replay-button" data-action="replay" title="Replay sample message traffic">${icon('reset')}<span>Replay demo</span></button>`;}
function roster(){return `<div class="roster-heading"><span class="eyebrow">YOUR AGENTS</span><span>Distinct roles.<br>One city.</span></div><div class="roster-list">${activeResidents().map(r=>`<button class="resident-button ${state.selected===r.id?'selected':''}" data-select="${r.id}" aria-label="Inspect ${residentName(r)}, ${r.role}, ${r.activity}">${avatar(r)}<span class="resident-copy"><strong>${residentName(r)}</strong><span>${r.role}</span><small class="${statusClass(r.activity)}">${r.activity}</small></span></button>`).join('')}</div><button class="assign-icon" data-action="assign" aria-label="Assign a demo task" title="Assign a demo task">${icon('plus')}</button>`;}
function commandHome(){return `<div class="command-eyebrow">${icon('message')} COMMAND ROOM <span class="tag">DEMO</span></div><h2>What are we<br>working on?</h2><p>Give ${residentName(resident('mayor'))} the outcome.<br>Your residents will take it from there.</p><button class="command-input" data-action="assign">Start with a goal…<span>${icon('arrow')}</span></button><div class="command-section"><span class="eyebrow">ON THE TABLE</span>${goalSummary()}</div><div class="command-section command-activity"><div class="section-line"><span class="eyebrow">RECENT EXCHANGES</span><button data-action="activity">All activity ${icon('arrow')}</button></div>${exchanges.slice(0,2).map(e=>`<button class="mini-event" data-road="${e.from==='mayor'?e.to:e.from}"><span class="mini-event-icon">${icon('send')}</span><span><strong>${residentName(resident(e.from))} <span class="muted">to</span> ${residentName(resident(e.to))}</strong><small>${e.purpose}</small></span>${icon('chevron')}</button>`).join('')}</div>`;}
function desktop(){return `<div class="desktop-ambient"><span class="desktop-orb orb-one"></span><span class="desktop-orb orb-two"></span><div class="desktop-intro"><span class="eyebrow">COMPACT COMPANION</span><h2>A little company.<br>Room for your work.</h2><p>Keep your city nearby.<br>Open command mode when it needs you.</p></div><div class="sample-document"><div class="document-toolbar"><i></i><i></i><i></i><span>My next project</span></div><div class="document-content"><span class="eyebrow">THINKING SPACE</span><h3>Make something<br>worth making.</h3><div class="document-lines"><span></span><span></span><span></span></div><div class="document-callout"><i></i><span>Space to focus. Your agents have the rest.</span></div><div class="document-lines short"><span></span><span></span></div></div></div><div class="desktop-note">A browser preview of the desktop layout.<br>Native always-on-top and click-through come in the full build.</div></div>`;}
function compactChrome(){return `<div class="compact-header"><span>${icon('town')} ${townName()} <small>DEMO</small></span><div><button data-action="pause" aria-label="${state.paused?'Continue':'Pause'} town">${icon(state.paused?'play':'pause')}</button><button data-action="expand" aria-label="Expand city">${icon('expand')}</button></div></div><button class="compact-decision" data-action="${state.approval==='pending'?'approvals':'goal'}"><span class="${state.approval==='pending'?'attention-dot':'local-dot'}"></span>${state.paused?'City paused':state.approval==='pending'?residentName(resident('critic'))+' needs a decision':state.phase==='review'?'Your result is ready':'All is quiet'} ${icon('chevron')}</button><div class="compact-under"><span>${activeResidents().length} residents <span class="muted">·</span> ${activeResidents().filter(active).length} working</span><span>${state.quiet?'Quiet mode':'Ambient preview'}</span></div>`;}
function panelShell(eyebrow:string,title:string,body:string,cls='',footer=''){
 const system=state.theme==='shadow';const caption=state.panel==='resident'?({Work:'STATUS',Equipment:'EQUIPMENT',Memory:'MEMORY',Skills:'SKILLS',History:'SESSIONS'}[state.tab]||'STATUS'):(({approvals:'NOTIFICATION',chief:'PLAYER',goal:'QUEST INFO',settings:'SYSTEM SETTINGS',towns:'DOMAINS',activity:'MESSAGE LOG',road:'ROUTES',outcomes:'ACCEPTED OUTCOMES'} as Record<string,string>)[state.panel||'']||'SYSTEM');
 return `<aside class="inspector ${cls} ${system?'system-window system-'+state.panel:''}" aria-label="${esc(title)}">${system?systemRails():''}<div class="inspector-header"><span class="eyebrow">${system?systemTitle(caption,state.panel==='approvals'):eyebrow}</span><button class="icon-button" data-action="close-panel" aria-label="Close inspector">${icon('close')}</button></div><div class="inspector-scroll">${body}</div>${footer?`<div class="inspector-fixed-footer">${footer}</div>`:''}</aside>`;
}
function residentQuickPanel(r:typeof residents[number]){
 const pending=r.id==='critic'&&state.approval==='pending',held=state.paused||['Paused','Pausing'].includes(r.activity),resting=r.activity==='Resting',planned=resting&&state.phase==='working';
 const running=state.tasks.find(t=>t.resident===r.id&&t.status==='Running'),queued=state.tasks.filter(t=>t.resident===r.id&&t.status==='Queued');
 const descriptions:Record<string,string>={Coordinating:'Delegating work and collecting the team’s findings.',Researching:'Checking primary sources for the recommendation.',Reading:'Reading source documentation and recording guarantees.',Waiting:'Waiting for the preceding handoff.',Review:'Checking the evidence before the Chief reviews the result.'};
 const latest=exchanges.find(e=>e.from===r.id||e.to===r.id);
 const description=held?'Work is paused. The current assignment is retained.':pending?'Waiting for your permission to read the recovery trace.':planned?'Waiting for the earlier steps to finish. No active turn.':resting?'No active turn. Ready for the next assignment.':running?'Working on your assigned task.':descriptions[r.activity]||'Ready for the next useful step.';
 return panelShell('AGENT ACTIVITY',residentName(r),`<div class="resident-profile">${avatar(r,true)}<div><h2>${residentName(r)}</h2><p>${r.role}</p></div><span class="activity-badge ${statusClass(r.activity)}">${state.paused?'Paused':r.activity}</span></div><section class="agent-current-work"><span class="eyebrow">${planned?'PLANNED WORK':resting?'AT HOME':'CURRENT TASK'}</span><h3>${esc(running?.title||(resting&&!planned?'No active task':r.task))}</h3><p>${description}</p>${pending?`<button class="attention-cta" data-action="approvals">${icon('shield')}Review request ${icon('arrow')}</button>`:''}</section>${latest?`<div class="agent-latest"><span>${icon('message')}</span><div><small>${latest.from===r.id?'LATEST SENT':'LATEST RECEIVED'} · ${esc(latest.status)}</small><p>${esc(latest.summary)}</p></div></div>`:queued.length?`<div class="agent-latest"><span>${icon('tasks')}</span><p>${queued.length} ${queued.length===1?'task':'tasks'} queued</p></div>`:''}`, 'house-menu agent-activity-menu', `${queued.length?`<div class="agent-queue-summary"><span>${queued.length} queued</span><button data-run-task="${queued[0].id}">Run next demo task ${icon('play')}</button></div>`:''}<div class="agent-knowledge-links"><button data-open-detail="Skills">${icon('spark')}Skills <span>${r.skills.length}</span></button><button data-open-detail="Memory">${icon('book')}Memory <span>${r.notes.length}</span></button></div><div class="agent-secondary-actions"><button data-action="assign" data-target="${r.id}">${icon('plus')}Assign task</button><button data-follow="${r.id}">${icon('eye')}${state.peek===r.id?'Room open':'Look inside'}</button><button data-action="expand-details" aria-label="More agent details" title="Queue, equipment, history and controls">${icon('chevron')}</button></div>`);
}
function chiefQuickPanel(){return panelShell('YOUR CHARACTER','Chief',`<div class="resident-profile"><span class="chief-crest">${icon('shield')}</span><div><h2>Chief</h2><p>Human owner</p></div></div><p class="chief-move-hint">Click anywhere in the world to teleport.</p><div class="chief-quick-actions"><button class="follow-agent" data-action="approvals">${icon('shield')}${state.approval==='pending'?'1 decision waiting':'No decisions waiting'}${icon('arrow')}</button><button class="follow-agent" data-peek="chief">${icon('eye')}Look inside your sanctuary${icon('arrow')}</button><button class="follow-agent" data-visit="chief">${icon('town')}Teleport home${icon('arrow')}</button></div><button class="text-button house-more" data-action="expand-details" aria-expanded="false">${state.theme==='shadow'?'Open Player menu':'More controls'} ${icon('chevron')}</button>`, 'house-menu');}
function residentPanel(){const r=resident(state.selected||'mayor');if(!state.detailsExpanded)return residentQuickPanel(r);const paused=r.activity==='Paused'||r.activity==='Pausing';const tasks=state.tasks.filter(t=>t.resident===r.id);return panelShell('RESIDENT / DEMO',residentName(r),`<button class="detail-back" data-action="collapse-details">${icon('left')} Back to activity</button><div class="resident-profile">${avatar(r,true)}<div><h2>${residentName(r)}</h2><p>${r.role} <span class="muted">/</span> ${home(r)}</p><span class="resident-state ${statusClass(r.activity)}"><i class="status-dot"></i>${r.activity}</span></div></div><div class="provider-line">${icon('terminal')}<span>Demo provider</span><span>Simulated</span></div><div class="inspector-tabs" role="tablist" aria-label="Resident details">${(state.theme==='shadow'?['Work','Equipment','Memory','Skills','History']:['Work','Memory','Skills','History']).map(t=>`<button role="tab" aria-selected="${state.tab===t}" data-tab="${t}" class="${state.tab===t?'active':''}">${t}</button>`).join('')}</div>
 ${state.tab==='Work'?`<section class="detail-section"><span class="eyebrow">CURRENT WORK</span><h3>${r.task}</h3><p>${r.id==='mayor'?'Keep the goal small, delegate useful work, and bring back a result with evidence.':r.activity==='Needs approval'?'Waiting for permission to read the sample recovery trace. Other independent work can continue.':r.activity==='Resting'?'Ready when the next useful task arrives. No background model calls.':r.activity==='Paused'?'Queue held. The simulated interruption was acknowledged. Continue starts a new demo turn.':'Part of the transport recommendation. This activity is supplied by the demo scenario.'}</p>${r.id==='critic'&&state.approval==='pending'?`<button class="attention-cta" data-action="approvals">${icon('shield')} Review pending request ${icon('arrow')}</button>`:''}<button class="follow-agent" data-follow="${r.id}">${icon('eye')} Look inside ${residentName(r)}'s home ${icon('arrow')}</button><button class="follow-agent" data-visit="${r.id}">${icon('route')} Teleport as Chief ${icon('arrow')}</button><div class="resident-actions"><button class="button primary" data-action="assign" data-target="${r.id}">${icon('plus')}Assign task</button><button class="button secondary" data-action="pause-resident" ${r.activity==='Resting'||r.activity==='Pausing'?'disabled':''}>${icon(paused?'play':'pause')}${r.activity==='Pausing'?'Pausing…':paused?'Continue':'Pause'}</button></div></section><section class="detail-section"><div class="section-line"><span class="eyebrow">QUEUE</span>${tag(String(tasks.length))}</div>${tasks.length?tasks.map(t=>`<div class="queued-task">${icon('clock')}<div><strong>${esc(t.title)}</strong><span>${t.status} · Demo workspace</span>${t.status==='Queued'?`<button class="run-task" data-run-task="${t.id}">${icon('play')}Run demo task</button>`:''}</div></div>`).join(''):'<div class="empty-inline">Nothing else queued. A quiet home is a good thing.</div>'}</section><section class="detail-section"><span class="eyebrow">HOME CONNECTION</span><button class="route-row" data-road="${r.id==='mayor'?'scout':r.id}">${icon('route')}<span>${r.id==='mayor'?residentName(r)+' ↔ '+residentName(resident('scout')):residentName(r)+' ↔ '+residentName(resident('mayor'))}<small>Two-way · Task messages</small></span>${icon('chevron')}</button></section>`:''}
 ${state.tab==='Equipment'&&state.theme==='shadow'?systemLoadout(r):''}
 ${state.tab==='Memory'?`<section class="detail-section"><div class="section-line"><span class="eyebrow">NOTES.md</span>${tag('REV 3')}</div><p>Knowledge this resident can carry into future work.</p>${r.notes.map((note,i)=>`<article class="memory-note"><span>${i===0?icon('book'):icon('link')}</span><p>${esc(note)}</p><small>${i===0?'Owner instruction':'Demo project note'} · Accepted</small></article>`).join('')}<form id="note-form"><label for="new-note">Add an owner note</label><textarea id="new-note" name="note" placeholder="Something worth remembering…" rows="3" required maxlength="500"></textarea><button class="button secondary" type="submit">${icon('plus')} Save demo note</button></form><small class="fine-print">Prototype notes stay in memory until this page is reloaded.</small></section>`:''}
 ${state.tab==='Skills'?`<section class="detail-section"><span class="eyebrow">ACCEPTED SKILLS</span><p>Procedures help residents work. They do not grant new permissions.</p>${state.theme==='cyber'?skillNetwork(r):''}${r.skills.map(s=>`<div class="skill-row">${icon('spark')}<div><strong>${s}</strong><span>Version 1 · Sample skill</span></div>${icon('check')}</div>`).join('')}</section>`:''}
 ${state.tab==='History'?`<section class="detail-section"><span class="eyebrow">SESSION HISTORY</span><div class="history-entry"><i class="status-dot active"></i><div><strong>Transport recommendation</strong><p>Current demo session. Memory revision 3.</p><small>No real provider thread attached</small></div></div><div class="history-entry"><i class="status-dot"></i><div><strong>Workspace conventions</strong><p>Accepted sample outcome. Owner instructions saved.</p><small>Earlier demo session</small></div></div></section>`:''}
 <div class="identity-footer"><span>RESIDENT ID</span><code>${esc(state.townId)} / ${r.id}</code><span>Same identity in both visual themes.</span></div>`);}
function approvalsPanel(){if(state.approval==='none')return panelShell('OWNER DECISIONS','Approvals',`<h2>No decisions waiting.</h2><p class="panel-intro">This town has no pending permission requests.</p>`);const pending=state.approval==='pending';return panelShell('OWNER DECISIONS','Approvals',`${state.theme==='shadow'?`<div class="system-notice-intro"><h2>${pending?'A decision is required.':'Your decision is recorded.'}</h2><p>${pending?'The following action needs the Chief’s permission.':'The resident will continue within your decision.'}</p></div>`:`<h2>Approvals<span class="count-badge">${pending?'1':'0'}</span></h2><p class="panel-intro">A single place for actions that need your say.</p>`}<div class="approval-card"><div class="approval-who">${avatar(resident('critic'))}<div><strong>${residentName(resident('critic'))} <span class="muted">/ Critic</span></strong><small>Transport recommendation</small></div>${tag(pending?'PENDING':state.approval.toUpperCase(),pending?'amber':'')}</div><h3>Read a sample recovery trace</h3><p>Check reconnection behavior against a recorded event trace.</p><dl class="scope-list"><div><dt>Operation</dt><dd>Read file</dd></div><div><dt>Exact scope</dt><dd><code>demo/traces/recovery.json</code></dd></div><div><dt>Permission</dt><dd>Read once. No writes.</dd></div><div><dt>Why you?</dt><dd>Outside the current demo workspace grant.</dd></div></dl><div class="denial-note">${icon('help')}<p>If denied, ${residentName(resident('critic'))} will use the existing sources and flag the trace check as unverified.</p></div>${pending?`${state.theme==='shadow'?'<p class="system-decision-question">Will you allow this request?</p>':''}<div class="approval-actions"><button class="button secondary" data-action="deny">Deny</button><button class="button primary" data-action="allow">${icon('check')}Allow once</button></div>`:`<div class="resolved-decision">${icon('check')}Demo request ${state.approval}. ${state.phase==='working'?'Review is continuing.':'The result is ready for review.'}</div><button class="button secondary full-width" data-action="goal">View result ${icon('arrow')}</button>`}</div><div class="demo-explanation">${icon('shield')}<p>This is a simulated permission request. Your real files and provider settings are untouched.</p></div>`);}
function goalPanel(){if(state.phase==='idle')return panelShell('TOWN GOALS','Goals',`<h2>Your first goal starts here.</h2><p class="panel-intro">This town has no active goal. Assign an outcome to its mayor or a specialist.</p><button class="button primary full-width" data-action="assign">${icon('plus')}New goal</button>`);return panelShell('GOAL G-003 / DEMO',state.goal,`<div class="section-line">${tag(state.phase==='working'?'IN PROGRESS':state.phase==='review'?'READY FOR REVIEW':'ACCEPTED',state.phase==='review'?'green':'')}<span class="tiny-code">2 active turns max</span></div><h2 class="goal-title">${esc(state.goal)}</h2><p class="panel-intro">Compare WebSocket, server-sent events, and local IPC. Recommend an approach with sources and an implementation checklist.</p><div class="goal-deliverables"><span class="eyebrow">THE PLAN</span>${[
 ['scout','Find primary sources','Complete'],['reader','Extract guarantees',state.phase==='working'?'Reading':'Complete'],['analyst','Compare the options',state.phase==='working'?'Waiting':'Complete'],['writer','Write & review the result',state.phase==='working'?'Waiting':'Complete']
 ].map(([id,title,status],i)=>`<div class="plan-step"><span class="step-number ${status==='Complete'?'done':''}">${status==='Complete'?icon('check'):String(i+1).padStart(2,'0')}</span><div><strong>${title}</strong><small>${residentName(resident(id))} · ${status}</small></div></div>`).join('')}</div>${state.phase==='working'?`<div class="plan-waiting">${icon('clock')}<p>${state.approval==='pending'?residentName(resident('critic'))+' needs your decision before the sample review finishes.':'Sample review is finishing.'}</p></div>${state.approval==='pending'?'<button class="button primary full-width" data-action="approvals">Review the request '+icon('arrow')+'</button>':''}`:`<section class="sample-result"><div class="section-line"><span class="eyebrow">SAMPLE RESULT</span>${icon('book')}</div><h3>Use local IPC for the desktop core.</h3><p>Keep town commands local. A typed command channel avoids a permanent HTTP server. Add remote transports only when a tested provider needs them.</p><div class="result-meta"><span>4 sample sources</span><span>${state.approval==='denied'?'Trace unverified':'Critic reviewed'}</span></div><small>This sample text demonstrates the review flow. It is not a real research result.</small></section>${state.phase==='review'?`<button class="button primary full-width" data-action="accept">${icon('check')} Accept sample outcome</button><button class="text-button full-width" data-action="revision">Request a revision</button>`:`<div class="accepted-note">${icon('spark')}Accepted by you. The archive annex is now part of your city.</div>`}`}`,'wide');}
function activityPanel(){return panelShell('CITY RECORD / DEMO','Activity',`<h2>Life in the city</h2><p class="panel-intro">Messages have a sender, a purpose, and a route. Couriers are a view of these exchanges.</p><div class="event-list">${exchanges.map(e=>`<button class="event-card" data-road="${e.from==='mayor'?e.to:e.from}"><div class="section-line"><span class="tiny-code">${e.id}</span><span class="event-time">${e.time}</span></div><strong>${residentName(resident(e.from))} ${icon('arrow')} ${residentName(resident(e.to))}</strong><h4>${e.purpose}</h4><p>${e.summary}</p><span class="event-status">${icon('check')}${e.status}</span></button>`).join('')}</div><button class="button secondary full-width" data-action="replay">${icon('reset')} Replay message couriers</button>`);}
function roadPanel(){const id=state.selected&&state.selected!=='mayor'?state.selected:'scout';const r=resident(id);return panelShell('COMMUNICATION ROUTE / DEMO','Route inspector',`<div class="route-title">${icon('route')}<h2>${residentName(r)} <span>↔</span> ${residentName(resident('mayor'))}</h2></div><p class="panel-intro">A permitted connection between two persistent homes.</p><dl class="scope-list"><div><dt>Direction</dt><dd>Two-way</dd></div><div><dt>Purpose</dt><dd>Task requests and results</dd></div><div><dt>Route</dt><dd>Direct road</dd></div><div><dt>State</dt><dd>Enabled · Demo policy</dd></div></dl><section class="detail-section"><span class="eyebrow">USEFUL COLLABORATION</span><h3>8 of 12 qualifying exchanges</h3><div class="goal-progress"><span style="width:67%"></span></div><p>At 12 acknowledged result exchanges across at least 6 tasks, this road can become an established transit link.</p><small class="fine-print">A visual upgrade keeps the same permissions. These are sample counts.</small></section><section class="detail-section"><span class="eyebrow">RECENT EXCHANGE</span>${exchanges.filter(e=>e.from===id||e.to===id).map(e=>`<article class="road-message"><div>${tag(e.status)}<span class="tiny-code">${e.id}</span></div><h3>${e.purpose}</h3><p>${e.summary}</p></article>`).join('')||'<p>No recent messages on this road.</p>'}</section><div class="demo-explanation">${icon('route')}<p>Without a direct connection, a message can relay through valid mayor roads. No extra model call is needed to route it.</p></div>`);}
function outcomesPanel(){return panelShell('ACCEPTED WORK / DEMO','Outcomes',`<span class="eyebrow">A PLACE THAT GROWS WITH YOU</span><h2>${state.accepted} useful outcomes.</h2><p class="panel-intro">Your accepted work changes the settlement. Messages, tokens, and time spent watching do not.</p><div class="growth-illustration">${icon('town')}<span>STAGE 0${state.stage+1}</span><h3>${['Establishment','Expansion','Consolidation'][state.stage]}</h3><p>${['Seven homes. A shared starting point.','An archive annex and expanded specialist homes.','An established hub with connected rooftops and gate details.'][state.stage]}</p></div><div class="growth-track">${['0 · Establish','3 · Expand','10 · Consolidate'].map((s,i)=>`<span class="${state.stage>=i?'reached':''}"><i></i>${s}</span>`).join('')}</div><section class="detail-section"><span class="eyebrow">ACCEPTANCE LEDGER</span>${state.phase==='accepted'?`<div class="outcome-row">${icon('check')}<div><strong>${esc(state.goal)}</strong><small>Accepted now · +1 cosmetic progress</small></div></div>`:''}${state.townId==='afterlight'?`<div class="outcome-row">${icon('check')}<div><strong>Workspace conventions</strong><small>Sample accepted outcome</small></div></div><div class="outcome-row">${icon('check')}<div><strong>Project research brief</strong><small>Sample accepted outcome</small></div></div>`:''}</section><div class="evolution-actions"><button class="button secondary" data-action="expand-city">${icon('plus')}Expand</button><button class="button secondary" data-action="consolidate-city">${icon('minus')}Consolidate</button></div><small class="fine-print">Capacity can grow or consolidate. Retired residents retain their identity and memory. No inactivity penalty.</small>`);}
function settingsPanel(){return panelShell('CITY PREFERENCES','Settings',`<h2>Keep it light.</h2><p class="panel-intro">A small city should leave room for your real work.</p><section class="detail-section"><span class="eyebrow">PRESENTATION</span><div class="setting-row"><div><strong>Quiet mode</strong><small>No walking, pose animations, or speech bubbles.</small></div><button class="toggle ${state.quiet?'on':''}" role="switch" aria-checked="${state.quiet}" aria-label="Quiet mode" data-action="quiet"><span></span></button></div><div class="setting-row"><div><strong>Day and night</strong><small>Time changes light. Work stays independent.</small></div><span class="clock-readout">${clockLabel()}</span></div><div class="clock-modes" role="group" aria-label="Day and night cycle">${(['local','accelerated','fixed'] as const).map(mode=>`<button data-clock="${mode}" aria-pressed="${state.clockMode===mode}" class="${state.clockMode===mode?'selected':''}">${{local:'Local time',accelerated:'90s preview',fixed:'Fixed light'}[mode]}</button>`).join('')}</div>${state.clockMode==='fixed'?`<button class="button secondary full-width" data-action="lighting">Fixed ${state.lighting}. Change preset ${icon('sun')}</button>`:''}<div class="cycle-explanation">${state.clockMode==='local'?'Follows your computer clock with gradual dawn and dusk. No location permission.':state.clockMode==='accelerated'?'One full day every 90 seconds for this prototype. The clock continues when work is paused.':'Manual art inspection. Switch back to Local time for the evolving city.'}</div><div class="setting-row"><div><strong>Resident chatter</strong><small>Occasional scripted activity notes and quirks. No model calls.</small></div><button class="toggle ${state.chatter?'on':''}" role="switch" aria-checked="${state.chatter}" aria-label="Resident chatter" data-action="chatter"><span></span></button></div><div class="setting-row"><div><strong>Route markings</strong><small>See permitted home connections.</small></div><button class="toggle ${state.roads?'on':''}" role="switch" aria-checked="${state.roads}" aria-label="Route markings" data-action="roads"><span></span></button></div></section><section class="detail-section"><span class="eyebrow">PROVIDER</span><div class="provider-card">${icon('terminal')}<strong>No provider connected</strong><p>This design prototype uses in-memory sample state. Real execution and native desktop controls are part of the later build.</p></div></section><section class="detail-section"><span class="eyebrow">RENDERER</span><div class="renderer-info"><span>Original procedural 3D models</span><span>One rendering library: Three.js</span><span>Repeated static geometry is instanced</span><span>24 fps expanded · 12 fps compact, during work animations</span><span>Quiet redraws for changes and clock updates</span><span>Hidden views stop rendering</span></div><small class="fine-print">Native CPU and memory budgets remain unverified. No performance claim is made from this browser preview.</small></section>`);}
function renderPanel(){switch(state.panel){case'chief':return chiefPanel();case'resident':return residentPanel();case'approvals':return approvalsPanel();case'goal':return goalPanel();case'activity':return activityPanel();case'road':return roadPanel();case'outcomes':return outcomesPanel();case'settings':return settingsPanel();case'towns':return townsPanel();default:return '';}}
function switcher(){if(!import.meta.env.DEV)return '';return `<span class="prototype-label">DESIGN PROTOTYPE</span><button data-action="previous-variant" aria-label="Previous layout">${icon('left')}</button><div class="variant-name"><strong>${state.variant}</strong><span>${{A:'City first',B:'Command room',C:'Desktop companion'}[state.variant]}</span></div><button data-action="next-variant" aria-label="Next layout">${icon('chevron')}</button><div class="variant-dots">${(['A','B','C'] as Variant[]).map(v=>`<button data-variant="${v}" aria-label="Layout ${v}" aria-pressed="${state.variant===v}" class="${state.variant===v?'active':''}"></button>`).join('')}</div>`;}
let renderedPanelKey='';
function render(){
 const panelKey=`${state.panel}:${state.selected}:${state.tab}`;const panelScroll=renderedPanelKey===panelKey?(el('panel-slot').querySelector('.inspector-scroll')?.scrollTop||0):0;renderedPanelKey=panelKey;
 const focused=document.activeElement as HTMLElement|null;
 const focusAttribute=['action','tab','theme','select','variant'].find(key=>focused?.dataset?.[key]);
 const focusSelector=focusAttribute?`[data-${focusAttribute}="${CSS.escape(focused!.dataset[focusAttribute]!)}"]`:null;
 document.documentElement.dataset.theme=state.theme;app.className=`variant-${state.variant} ${state.panel?'has-panel':''} ${state.quiet?'quiet':''} ${!state.detailsExpanded&&(state.panel==='resident'||state.panel==='chief')?'brief-panel':''}`;el('header').innerHTML=header();el('rail').innerHTML=rail();el('heading').innerHTML=heading();el('goal-summary').innerHTML=goalSummary();el('command-home').innerHTML=commandHome();el('map-controls').innerHTML=controls();el('map-legend').innerHTML=`<span class="compass">N <i>↗</i></span><span>${icon('route')}Generated roads</span><span class="legend-message"><i></i>Message courier</span>`;el('roster').innerHTML=roster();el('panel-slot').innerHTML=renderPanel();const panelScroller=el('panel-slot').querySelector('.inspector-scroll');if(panelScroller)panelScroller.scrollTop=panelScroll;el('footer').innerHTML=`<div><span class="local-dot"></span>Demo mode<span class="footer-separator">·</span>No provider connected<span class="footer-separator">·</span>3D prototype / simulated work</div><div><button data-action="pause">${icon(state.paused?'play':'pause')}${state.paused?'Continue city':'Pause city'}</button><button class="new-goal" data-action="assign">${icon('plus')}New goal</button></div>`;el('switcher').innerHTML=switcher();el('toast').textContent=state.toast;el('toast').classList.toggle('visible',!!state.toast);el('scene-state').textContent=state.peek?`Cutaway · ${state.peek==='chief'?'Chief headquarters':residentName(resident(state.peek))+' at home'}`:state.paused?'Scheduling held · demo':state.phase==='accepted'?'Settled & quiet · demo':'Demo district · no live execution';el('compact-chrome').innerHTML=compactChrome();el('city-actions').innerHTML=`<button data-action="chief">${icon('town')}Chief</button><button data-action="towns">${icon('grid')} Towns <span>${towns.length}</span></button><button data-action="expand-city">${icon('plus')}Expand</button><button data-action="consolidate-city">${icon('minus')}Consolidate</button>`;renderClock();if(!el('desktop').innerHTML)el('desktop').innerHTML=desktop();if(focused&&!focused.isConnected&&focusSelector)app.querySelector<HTMLElement>(focusSelector)?.focus({preventScroll:true});scene.syncOverlay();}
subscribe(render);render();
let lastFocused:HTMLElement|null=null;
function closeModal(){el('modal-slot').innerHTML='';
 if(lastFocused?.isConnected)lastFocused.focus();
 else if(lastFocused?.dataset.action)app.querySelector<HTMLElement>(`[data-action="${CSS.escape(lastFocused.dataset.action)}"]`)?.focus();
 }
function showAssign(target='mayor'){lastFocused=document.activeElement as HTMLElement;el('modal-slot').innerHTML=`<div class="modal-backdrop"><section class="assignment-modal" role="dialog" aria-modal="true" aria-labelledby="assignment-title"><div class="inspector-header"><span class="eyebrow">A NEW PIECE OF WORK / DEMO</span><button class="icon-button" data-action="close-modal" aria-label="Close assignment">${icon('close')}</button></div><h2 id="assignment-title">What should we work on?</h2><p>Start with an outcome. Give it to ${residentName(resident('mayor'))}, or go directly to a specialist.</p><form id="assign-form"><label for="task-title">Your goal</label><textarea id="task-title" name="goal" placeholder="Compare three approaches. Bring back a recommendation with sources…" rows="4" required maxlength="1000"></textarea><div class="form-two-column"><div><label for="resident-target">Assign to</label><select id="resident-target" name="resident">${activeResidents().map(r=>`<option value="${r.id}" ${r.id===target?'selected':''}>${residentName(r)} · ${r.role}</option>`).join('')}</select></div><div><label for="workspace">Workspace</label><select id="workspace"><option>Demo workspace</option></select></div></div><div class="assignment-scope">${icon('shield')}<p>Demo only. This queues a sample task in memory. It does not contact a provider or modify your files.</p></div><button type="submit" class="button primary full-width">${icon('send')} Queue demo task</button></form></section></div>`;el('task-title').focus();}
function showAbout(){lastFocused=document.activeElement as HTMLElement;el('modal-slot').innerHTML=`<div class="modal-backdrop"><section class="assignment-modal about-modal" role="dialog" aria-modal="true" aria-labelledby="about-title"><div class="inspector-header"><span class="eyebrow">FOR YOUR DESIGN APPROVAL</span><button class="icon-button" data-action="close-modal" aria-label="Close about">${icon('close')}</button></div><h2 id="about-title">A small city.<br>A useful team.</h2><p>Explore three layouts and two original art directions before we build the real desktop application.</p><div class="about-layouts">${(['A','B','C'] as Variant[]).map(v=>`<button data-about-variant="${v}"><span>${v}</span><div><strong>${{A:'City first',B:'Command room',C:'Desktop companion'}[v]}</strong><small>${{A:'The settlement leads. Details open when needed.',B:'Start with a goal. Keep the city alongside it.',C:'A small ambient town beside your everyday work.'}[v]}</small></div>${icon('arrow')}</button>`).join('')}</div><div class="assignment-scope">${icon('help')}<p>Work and permissions are simulated. Towns, layouts, and memory are interactive prototype state. Changes reset on reload. Native overlay behavior and real provider integration await the full build.</p></div></section></div>`;el('modal-slot').querySelector<HTMLButtonElement>('button')?.focus();}
function cycle(dir:number){const all:Variant[]=['A','B','C'];setVariant(all[(all.indexOf(state.variant)+dir+3)%3]);}
app.addEventListener('click',event=>{const target=(event.target as Element).closest<HTMLElement>('button');if(!target)return;
 if(target.dataset.openDetail){update(()=>{state.detailsExpanded=true;state.tab=target.dataset.openDetail!;});return;}if(target.dataset.cameraMode){update(()=>state.cameraMode=target.dataset.cameraMode as 'pan'|'orbit');return;}if(target.dataset.inspectHome){scene.inspectHome(target.dataset.inspectHome);return;}if(target.dataset.equipment){update(()=>state.loadoutSlot=target.dataset.equipment as 'tool'|'attire');return;}if(target.dataset.chiefSection){document.querySelector(`section[data-chief-section="${CSS.escape(target.dataset.chiefSection)}"]`)?.scrollIntoView({block:'start',behavior:state.quiet?'auto':'smooth'});return;}if(target.dataset.visit){scene.visitHome(target.dataset.visit);return;}if(target.dataset.peek){scene.follow(target.dataset.peek);return;}if(target.dataset.clock){setClockMode(target.dataset.clock as typeof state.clockMode);return;}if(target.dataset.town){switchTown(target.dataset.town);return;}if(target.dataset.recall){recallResident(target.dataset.recall);return;}if(target.dataset.follow){scene.follow(target.dataset.follow);return;}if(target.dataset.runTask){update(()=>{const task=state.tasks.find(t=>t.id===target.dataset.runTask)!;task.status='Running';const r=resident(task.resident);r.activity=r.role==='Reader'?'Reading':'Researching';r.task=task.title;state.phase='working';state.goal=task.title;});return;}if(target.dataset.select){scene.inspectHome(target.dataset.select);return;}if(target.dataset.theme){setTheme(target.dataset.theme as 'cyber'|'shadow');return;}if(target.dataset.variant){setVariant(target.dataset.variant as Variant);return;}if(target.dataset.aboutVariant){closeModal();setVariant(target.dataset.aboutVariant as Variant);return;}if(target.dataset.tab){update(()=>state.tab=target.dataset.tab!);return;}if(target.dataset.road){update(()=>{state.selected=target.dataset.road!;state.panel='road';});return;}
 switch(target.dataset.action){case'town':case'close-panel':update(()=>{state.panel=null;state.selected=null;state.peek=null;});break;case'residents':scene.inspectHome(state.selected||'mayor');break;case'expand-details':update(()=>state.detailsExpanded=true);break;case'collapse-details':update(()=>{state.detailsExpanded=false;state.tab='Work';});break;case'locate-chief':scene.locateChief();break;case'chief':update(()=>{state.panel='chief';state.detailsExpanded=false;});break;case'towns':case'goal':case'approvals':case'activity':case'outcomes':case'settings':update(()=>state.panel=target.dataset.action as typeof state.panel);break;case'chief-estate':scene.focusChief();break;case'close-cutaway':update(()=>state.peek=null);break;case'chatter':update(()=>state.chatter=!state.chatter);break;case'courier':if(state.paused){toast('Continue the city to send a demo courier.');break;}if(scene.stats().courier){toast('A courier is already carrying the source index.');break;}update(()=>state.courierSerial++);toast(`Demo courier dispatched via ${residentName(resident('mayor'))}.`);break;case'demand-high':previewDemand(true);break;case'demand-low':previewDemand(false);break;case'expand-city':expandCity();break;case'consolidate-city':consolidateCity();break;case'relayout':relayout();break;case'orbit':scene.rotate();break;case'pause':pauseTown();break;case'pause-resident':pauseResident(resident(state.selected||'mayor'));break;case'allow':decide(true);break;case'deny':decide(false);break;case'accept':accept();break;case'revision':update(()=>{state.phase='working';state.approval='pending';resident('mayor').activity='Coordinating';resident('critic').activity='Needs approval';});toast('A sample revision is queued. No additional acceptance credit.');break;case'assign':showAssign(target.dataset.target);break;case'close-modal':closeModal();break;case'about':showAbout();break;case'quiet':update(()=>state.quiet=!state.quiet);break;case'roads':update(()=>state.roads=!state.roads);break;case'lighting':update(()=>state.lighting=state.lighting==='night'?'dusk':state.lighting==='dusk'?'day':'night');break;case'zoom-in':update(()=>state.zoom=Math.min(2.6,state.zoom+.1));break;case'zoom-out':update(()=>state.zoom=Math.max(.7,state.zoom-.1));break;case'reset-camera':scene.reset();break;case'replay':replay();break;case'previous-variant':cycle(-1);break;case'next-variant':cycle(1);break;case'expand':setVariant('A');break;case'preview-growth':update(()=>state.stage=(state.stage+1)%3);toast('Appearance preview only. Your demo acceptance ledger is unchanged.');break;}
});
app.addEventListener('submit',event=>{const form=event.target as HTMLFormElement;event.preventDefault();const data=new FormData(form);if(form.id==='town-form'){const name=String(data.get('name')||'').trim(),purpose=String(data.get('purpose')||'').trim();if(name)foundTown(name,purpose||'Independent workspace');}else if(form.id==='assign-form'){const title=String(data.get('goal')||'').trim(),id=String(data.get('resident'));if(!title)return;update(()=>{state.tasks.push({id:`TASK-${String(state.tasks.length+4).padStart(3,'0')}`,title,resident:id,status:'Queued'});state.selected=id;state.panel='resident';state.tab='Work';state.detailsExpanded=false;});closeModal();toast(`Demo task queued for ${residentName(resident(id))}.`);}else if(form.id==='note-form'){const note=String(data.get('note')||'').trim();if(note){update(()=>resident(state.selected||'mayor').notes.push(note));toast('Owner note saved in prototype memory.');}}});
document.addEventListener('keydown',e=>{const modal=el('modal-slot').querySelector('[role="dialog"]');if(e.key==='Escape'){if(modal)closeModal();else update(()=>{state.panel=null;state.selected=null;state.peek=null;});return;}if(modal&&e.key==='Tab'){const focusable=[...modal.querySelectorAll<HTMLElement>('button, textarea, input, select, [tabindex="0"]')].filter(e=>!e.hasAttribute('disabled'));const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}
 if(modal||(e.target as Element).closest('input,textarea,select,[contenteditable]'))return;if(e.key==='ArrowRight'){e.preventDefault();cycle(1);}if(e.key==='ArrowLeft'){e.preventDefault();cycle(-1);}
});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);update(()=>{state.variant=(p.get('variant')||'A') as Variant;state.theme=p.get('theme')==='shadow'?'shadow':'cyber';});});

function townsPanel(){return panelShell(state.theme==='cyber'?'CITY NETWORK / DEMO':'SYSTEM / DOMAINS','Towns',`<h2>${state.theme==='cyber'?'Your city network.':'Your domains.'}</h2><p class="panel-intro">Found towns for separate work. Each has its own residents, tasks, notes, and progress.</p><div class="town-list">${towns.map(t=>`<button class="town-card ${t.id===state.townId?'selected':''}" data-town="${t.id}"><span class="town-symbol">${icon('town')}</span><span><strong>${esc(t.name)}</strong><small>${esc(t.purpose)}</small><em>${(t.id===state.townId?activeResidents():t.people.filter(r=>!r.retired)).length} homes · ${t.id===state.townId?'Current town':'Open town'}</em></span>${icon('arrow')}</button>`).join('')}</div><section class="detail-section"><span class="eyebrow">FOUND A TOWN</span><form id="town-form"><label for="town-name">Town name</label><input id="town-name" name="name" placeholder="e.g. Glass Harbor" required maxlength="35"><label for="town-purpose">What is this town for?</label><input id="town-purpose" name="purpose" placeholder="A project, research area, or team" maxlength="80"><button class="button primary full-width" type="submit">${icon('plus')}Found town</button></form></section><section class="detail-section"><span class="eyebrow">WORKLOAD-DRIVEN CAPACITY / DEMO</span><p>Watch a burst of work create extra homes. Let that work settle to consolidate them again.</p><div class="evolution-actions"><button class="button secondary" data-action="demand-high">${icon('activity')}Work arrives</button><button class="button secondary" data-action="demand-low">${icon('check')}Work settles</button></div><small class="fine-print">Demand ${state.demand}. Cosmetic capacity adapts; provider limits stay unchanged.</small></section><section class="detail-section"><span class="eyebrow">ADAPT ${townName().toUpperCase()}</span><p>Expand when extra capacity is useful. Consolidate unused annexes and idle homes when less is needed.</p><div class="evolution-actions"><button class="button secondary" data-action="expand-city">${icon('plus')}Expand</button><button class="button secondary" data-action="consolidate-city">${icon('minus')}Consolidate</button></div><button class="button secondary full-width" data-action="relayout">${icon('route')}Replan layout & generate paths</button><small class="fine-print">Appearance stage ${state.stage+1} of 3. ${activeResidents().length} active homes. Paths avoid building footprints. Layout changes grant no permissions.</small></section>${residents.some(r=>r.retired)?`<section class="detail-section"><span class="eyebrow">RETIRED HOMES / MEMORY RETAINED</span>${residents.filter(r=>r.retired).map(r=>`<div class="retired-row"><span>${residentName(r)}<small>${r.role} · ${r.notes.length} notes preserved</small></span><button class="button secondary small" data-recall="${r.id}" aria-label="Recall ${residentName(r)}">Recall</button></div>`).join('')}</section>`:''}<div class="demo-explanation">${icon('book')}<p>Consolidation keeps a resident's identity and memory. Inactivity causes no decay. This prototype resets on reload.</p></div>`);}
function renderClock(){el('world-clock').innerHTML=`<button data-action="settings" aria-label="Configure city clock"><span class="clock-orb ${clockHours()>6&&clockHours()<19?'day':'night'}"></span><span><strong>${clockLabel()}</strong><small>${state.clockMode==='local'?'LOCAL TIME':state.clockMode==='accelerated'?'90 SECOND DAY':'FIXED LIGHT'}</small></span></button>`;document.querySelectorAll('.clock-readout').forEach(node=>node.textContent=clockLabel());}
let clockTicker=0;
function tickClock(){clearTimeout(clockTicker);if(document.hidden)return;renderClock();if(state.clockMode==='fixed')return;clockTicker=window.setTimeout(tickClock,state.clockMode==='accelerated'?1000:10000);}
subscribe(tickClock);document.addEventListener('visibilitychange',tickClock);tickClock();

function chiefPanel(){if(!state.detailsExpanded)return chiefQuickPanel();if(state.theme==='shadow')return systemChiefPanel();return panelShell('CHIEF / YOUR HOME','Chief',`<button class="detail-back" data-action="collapse-details">${icon('left')} Less detail</button><div class="chief-intro"><span class="chief-crest">${icon('shield')}</span><span class="eyebrow">CHIEF SANCTUARY</span><h2>Your place in the city.</h2><p>You set direction. ${residentName(resident('mayor'))} coordinates the team. Every decision can come back to you.</p></div><section class="detail-section"><span class="eyebrow">LETTERBOX</span><button class="chief-mail" data-action="approvals"><span>${icon('shield')}<strong>${state.approval==='pending'?'1 request needs you':'No requests waiting'}</strong><small>Review scope. Allow once or deny.</small></span>${icon('arrow')}</button><button class="chief-mail" data-action="goal"><span>${icon('check')}<strong>${state.phase==='review'?'A result is ready':'Current goal'}</strong><small>${esc(state.goal)}</small></span>${icon('arrow')}</button><button class="button primary full-width" data-action="assign">${icon('plus')}Give the mayor a goal</button></section><section class="detail-section"><span class="eyebrow">YOUR HOME & VISITS</span><p>Your white coat and crest identify you separately from the mayor. Your sanctuary is separate from the city. Click anywhere in the world to teleport.</p><button class="follow-agent" data-action="chief-estate">${icon('eye')}View your sanctuary ${icon('arrow')}</button><button class="follow-agent" data-peek="chief">${icon('eye')}Look inside headquarters ${icon('arrow')}</button>${state.peek?'<button class="follow-agent" data-action="close-cutaway">Close cutaway</button>':''}<button class="follow-agent" data-visit="chief">${icon('town')}Teleport home</button><div class="chief-visits">${activeResidents().map(r=>`<button data-visit="${r.id}"><strong>${residentName(r)}</strong><small>${r.role}</small>${icon('route')}</button>`).join('')}</div><small class="fine-print">A visit is a visual demo. The Chief retains owner authority in every town.</small></section><section class="detail-section"><span class="eyebrow">MESSAGE DELIVERY / DEMO</span><p>A small robot carries ${residentName(resident('scout'))}'s source index to ${residentName(resident('reader'))} through the mayor hub. Residents work indoors between handoffs.</p><button class="button secondary full-width" data-action="courier">${icon('send')}Send a demo courier</button><button class="follow-agent" data-action="activity">${icon('activity')}Read the delivery log ${icon('arrow')}</button><small class="fine-print">Speech bubbles are scripted flavor text. Work and delivery stay simulated until the full build is approved.</small></section><button class="button secondary full-width" data-action="towns">${icon('grid')}Manage towns & capacity</button>`);}

function skillNetwork(r:typeof residents[number]){const points=[[25,22],[75,22],[50,84],[18,65],[82,65]];return `<div class="cyber-skill-network" role="img" aria-label="${esc(residentName(r))}'s accepted skills: ${esc(r.skills.join(', '))}"><svg viewBox="0 0 300 270" preserveAspectRatio="none" aria-hidden="true">${r.skills.slice(0,5).map((_,i)=>`<path d="M150 140 L${points[i][0]*3} ${points[i][1]*2.7}"/>`).join('')}</svg><div class="cyber-skill-node core" style="left:50%;top:52%"><span><strong>${esc(residentName(r))}</strong><small>${esc(r.role).toUpperCase()}</small></span></div>${r.skills.slice(0,5).map((skill,i)=>`<div class="cyber-skill-node" style="left:${points[i][0]}%;top:${points[i][1]}%"><span>${icon('spark')}<strong>${esc(skill)}</strong><small>ACCEPTED PROCEDURE</small></span></div>`).join('')}</div>`;}

function systemTitle(text:string,notice=false){return `<span class="system-title-group"><span class="system-title-icon" aria-hidden="true">${notice?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="12" cy="12" r="9"/><path d="M12 5.5v9m0 2.5v1"/></svg>':icon(text==='PLAYER'?'users':text==='EQUIPMENT'?'shield':text==='QUEST INFO'?'tasks':'spark')}</span><span class="system-caption">${text}</span></span>`;}
function systemRails(){return `<span class="system-frame-rail top" aria-hidden="true"><svg viewBox="0 0 500 22" preserveAspectRatio="none"><path d="M1 3H110l12 8h252l12-8H499M1 8H108l12 8h256l12-8H499M1 18H106l10 3h270l12-3H499"/><path class="rail-core" d="M4 5h104l14 8h252l12-8h110M210 1l8 17h64l8-17"/></svg></span><span class="system-frame-rail bottom" aria-hidden="true"><svg viewBox="0 0 500 22" preserveAspectRatio="none"><path d="M1 3H110l12 8h252l12-8H499M1 8H108l12 8h256l12-8H499M1 18H106l10 3h270l12-3H499"/><path class="rail-core" d="M4 5h104l14 8h252l12-8h110M210 1l8 17h64l8-17"/></svg></span>`;}
function systemFigure(r:typeof residents[number]){return `<svg class="system-figure" viewBox="0 0 112 250" fill="none" stroke="currentColor" stroke-width="1.2" aria-hidden="true"><path class="figure-cape" d="M31 49 20 197l20-12m41-136 11 148-20-12"/><path d="m44 12 12-7 12 7v20l-12 8-12-8Zm0 5 12 5 12-5M49 28h14M51 42h10v5H51Zm-11 7 16 5 16-5 5 37-21 10-21-10ZM42 63l14 6 14-6M56 54v37m-9-15 9-7 9 7-9 9ZM31 48l-13 6-2 14 15 8 6-12Zm50 0 13 6 2 14-15 8-6-12ZM16 74l13 6-5 30-12-3Zm80 0-13 6 5 30 12-3ZM11 113l13 3-4 28-13-3Zm90 0-13 3 4 28 13-3ZM7 145l13 3 1 11-7 5-8-9Zm98 0-13 3-1 11 7 5 8-9ZM35 92l21 9 21-9-2 22-19 8-19-8Zm3 28 15 7-3 34-17-3Zm36 0-15 7 3 34 17-3ZM33 163l17 4-2 15-17-2Zm46 0-17 4 2 15 17-2ZM31 185l17 3-2 36-18-2Zm50 0-17 3 2 36 18-2ZM28 226l18 3 2 12-9 4-18-5Zm56 0-18 3-2 12 9 4 18-5Z"/>${r.id==='chief'?'<path class="figure-emblem" d="m50 7 2-7 4 4 4-4 2 7M43 100l13 8 13-8M42 116l-8 57 22-9 22 9-8-57"/>':r.role==='Reader'?'<path class="figure-tool" d="m83 102 13-4 14 6-4 26-12-6-15 2Zm13-4-2 26"/>':r.role==='Critic'?'<path class="figure-tool" d="m18 60 2 5-6 112-4 8-3-8L16 65ZM0 157l25 2"/>':r.role==='Analyst'?'<circle class="figure-tool" cx="98" cy="115" r="12"/>':'<path class="figure-tool" d="m2 112 22 5-5 25-20-5ZM3 119l14 3m-15 3 13 3"/>'}</svg>`;}
function systemLoadout(r:typeof residents[number],owner=false){
 const tool:Record<string,[string,string,string]>={Mayor:['terminal','Command handset','The handset shown on This resident’s model represents coordination.'],Scout:['route','Survey gauntlet','This resident carries scouting equipment and twin back blades.'],Reader:['book','Source codex','This resident’s book represents reading and source extraction.'],Analyst:['spark','Analysis orb','This resident’s orb represents comparison and analysis.'],Writer:['tasks','Drafting tablet','This resident carries a writing tablet and stylus.'],Editor:['tasks','Revision tablet','This resident carries a revision tablet and stylus.'],Critic:['shield','Critic’s blade','This resident’s blade represents scrutiny and challenge.'],Chief:['terminal','Chief terminal','Your owner controls remain available throughout the city.']};
 const item=tool[r.role]||['terminal','Role terminal','A visual tool for this resident’s role.'];
 const slots=owner?[
  ['shield','Letterbox',state.approval==='pending'?'1 pending':'Clear','data-action="approvals"'],['tasks','New goal','Give direction','data-action="assign"'],['town','Headquarters','Look inside','data-peek="chief"'],['route','Visits','Choose resident','data-chief-section="visits"'],['grid','Domains',`${towns.length} town${towns.length===1?'':'s'}`,'data-action="towns"'],['archive','Outcomes',`${state.accepted} accepted`,'data-action="outcomes"']
 ]:[
  ['shield','Shadow attire','Equipped','data-equipment="attire"'],[item[0],item[1],'Equipped','data-equipment="tool"'],['book','Memory',`${r.notes.length} notes`,'data-tab="Memory"'],['spark','Skills',`${r.skills.length} accepted`,'data-tab="Skills"'],['town','Home','Look inside',`data-follow="${r.id}"`],['route','Connection','Via '+residentName(resident('mayor')),`data-road="${r.id==='mayor'?'scout':r.id}"`]
 ];
 return `<section class="system-loadout"><div class="system-section-caption">${owner?'CHIEF ACCESS':'ROLE EQUIPMENT'}</div><div class="system-loadout-diagram"><svg class="loadout-connectors" viewBox="0 0 350 300" preserveAspectRatio="none" aria-hidden="true"><path d="M74 45h40l20 22M276 45h-40l-20 22M74 150h45M276 150h-45M74 255h44l20-30M276 255h-44l-20-30"/></svg><div class="system-loadout-figure">${systemFigure(r)}<small>${owner?'CHIEF':'SHADOW RESIDENT'}</small></div>${slots.map(([ic,label,detail,action],i)=>`<button class="system-equipment-slot slot-${i} ${!owner&&action===`data-equipment="${state.loadoutSlot}"`?'selected':''}" ${action} ${action.includes('data-equipment')?`aria-pressed="${action.includes(state.loadoutSlot)}"`:''}>${icon(ic)}<strong>${esc(label)}</strong><small>${esc(detail)}</small></button>`).join('')}</div>${owner?'':`<div class="system-equipment-readout"><span class="eyebrow">EQUIPPED VISUAL / DEMO</span><h3>${state.loadoutSlot==='attire'?'Shadow armor & cloak':item[1]}</h3><p>${state.loadoutSlot==='attire'?'The helmet, armor, boots, and cloak match this resident’s city model.':item[2]} Equipment is cosmetic. Work permissions stay with the resident’s scope.</p></div>`}</section>`;
}
function systemChiefPanel(){return panelShell('CHIEF / HUMAN OWNER','Chief',`<button class="detail-back" data-action="collapse-details">${icon('left')} Less detail</button><div class="system-player-identity"><span class="eyebrow">HUMAN OWNER</span><h2>Chief</h2><p>${townName()} <span> / </span> Player sanctuary</p><span class="system-player-authority">${icon('shield')}Owner authority</span></div><div class="system-player-stats"><button data-action="approvals"><span>Decisions waiting</span><strong>${state.approval==='pending'?1:0}</strong></button><button data-action="outcomes"><span>Accepted outcomes</span><strong>${state.accepted}</strong></button></div>${systemLoadout(chief,true)}<section class="detail-section system-player-goal"><span class="eyebrow">CURRENT QUEST</span><h3>${esc(state.goal)}</h3><button class="button secondary full-width" data-action="goal">Open quest info ${icon('arrow')}</button></section><button class="button secondary full-width" data-action="chief-estate">${icon('eye')}View your sanctuary</button><section class="detail-section" data-chief-section="visits"><span class="eyebrow">YOUR HOME & VISITS</span><p>Your sanctuary has no road connections. Click the world to teleport, or choose a resident below. Your character stays visible.</p><button class="follow-agent" data-visit="chief">${icon('town')}Teleport home</button><div class="chief-visits">${activeResidents().map(r=>`<button data-visit="${r.id}"><strong>${residentName(r)}</strong><small>${r.role}</small>${icon('route')}</button>`).join('')}</div>${state.peek?'<button class="button secondary full-width" data-action="close-cutaway">Close cutaway</button>':''}</section><section class="detail-section"><span class="eyebrow">MESSAGE DELIVERY / DEMO</span><p>A courier carries the sample source index through the mayor hub.</p><button class="button secondary full-width" data-action="courier">${icon('send')}Send a demo courier</button><button class="follow-agent" data-action="activity">${icon('activity')}Read the delivery log ${icon('arrow')}</button></section><small class="fine-print">Prototype controls use sample state. Your authority and identity stay the same in both themes.</small>`);}
